import{_ as t,o as a,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy learning foundations","description":"October 23 v2 alignment: GDD v2 makes restoration actions and the shared fictional transaction the main learning loop. Contextual Quiz supports reasoning; Wordle and BlockMatc","frontmatter":{"title":"Chainy learning foundations","description":"October 23 v2 alignment: GDD v2 makes restoration actions and the shared fictional transaction the main learning loop. Contextual Quiz supports reasoning; Wordle and BlockMatc","source":"docs/learning-foundations.md","category":"Other documents","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/learning-foundations.md","filePath":"content/docs/learning-foundations.md"}'),r={name:"content/docs/learning-foundations.md"};function i(s,e,c,d,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-learning-foundations">Chainy learning foundations<a class="header-anchor" href="#chainy-learning-foundations" aria-label="Link to this section">​</a></h1><p>October 23 v2 alignment: <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a> makes restoration actions and the shared fictional transaction the main learning loop. Contextual Quiz supports reasoning; Wordle and BlockMatch are retained for later vocabulary/relationship practice. The older mini-game teaching guidance below applies only where those activities are delivered, not as the beta scope. A01–A03 requires actual example-based classification with separate practice/final evidence; authored assistant advice is a different later activity. Quest/encyclopedia completion is not mastery. See the <a href="/Chainy-Docs/content/docs/planning/quest-curriculum.html">current quest/source map</a>.</p><p>Owners: Sherwin (Design Lead) and Sean (Docs Lead). October 12, 2026.</p><p>The subject scope remains introductory Web3, Blockchain and AI for ages 12–17. V2&#39;s restoration quests and shared record are the main delivery format; contextual Quiz supports them. Wordle and BlockMatch are later activities. The previous nine-lesson curriculum is <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/learning-foundations.html">historical</a>; it does not override the new bounded repair/classifier contracts.</p><h2 id="one-small-content-sheet">One small content sheet<a class="header-anchor" href="#one-small-content-sheet" aria-label="Link to this section">​</a></h2><p>For every activity, record: <strong>topic → one learning objective → explanation/example → player task → correct answer or matching rule → feedback → source</strong>. Add the mode and a stable content identifier so Christian can connect the content to progress.</p><table><thead><tr><th>Mode</th><th>Useful learning role</th><th>What the author must supply</th></tr></thead><tbody><tr><td>Restoration quests (CORE)</td><td>Make and explain a consequential fictional action</td><td>Goal, prerequisite, action, expected record/world change, error explanation and source</td></tr><tr><td>Example-trained classifier (STRETCH)</td><td>Compare training choices with unseen-case behavior</td><td>Approved labels/features, separate training/practice/final cases and truthful limits</td></tr><tr><td>Quiz</td><td>Check understanding and choices</td><td>Question, choices, correct answer and explanation for each answer</td></tr><tr><td>Wordle</td><td>Reinforce a taught term</td><td>Allowed word, plain-language definition/context, hint and explanation after play</td></tr><tr><td>BlockMatch</td><td>Practice a meaningful relationship</td><td>Matchable items, the relation that makes a match correct, examples/non-examples and explanation</td></tr></tbody></table><p>Word spelling, speed or a high matching score alone does not establish concept understanding. Use a short explanation or follow-up question where needed.</p><h2 id="writing-and-review">Writing and review<a class="header-anchor" href="#writing-and-review" aria-label="Link to this section">​</a></h2><p>Use familiar examples before technical terms. Keep instructions short; avoid assuming prior computer or cryptocurrency experience. Essential instructions must work without audio. Test whether players can explain what they learned, not just what they tapped.</p><p>Sherwin approves the gameplay purpose. Sean checks wording and sources. Christian checks technical accuracy and implementability; seek subject/adviser review where the team lacks expertise. Luis and Miguel check whether pictures and screens support the explanation.</p><p>Do not automatically reuse the old questions: first check whether the new game actually teaches what they ask. Freeze the final content list and answer keys before beta; record later corrections.</p><h2 id="before-content-production-expands">Before content production expands<a class="header-anchor" href="#before-content-production-expands" aria-label="Link to this section">​</a></h2><p>The design/rules cards freeze core quest and contextual-feedback examples. The core verification card proves quest → save → reload; the content card packages the quest log, encyclopedia and explanations. Follow W01–W04 and B01–B03/demo B07 for beta, with conditional A01–A03 and explicit FULL/LATER SERVICE boundaries. The three-world full roadmap is design intent, not a claim that all worlds are delivered.</p><p>Research pre/post questions belong to the adviser-reviewed evaluation instrument and should not be treated as interchangeable with repeated in-game practice. See <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation</a>.</p></div>',1)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
